const rows = $input.all().map(i => i.json);
const trg = $("01 Gmail Trigger - RQ Recibida").first().json;
const subject = String(trg.subject || trg.Subject || "");
const m = subject.match(/RQ[-\s]?0*(\d+)/i);
const folio = m ? ("RQ-" + String(m[1]).padStart(4, "0")) : ("RQ-" + $now.toFormat("yyyyLLddHHmm"));
let remitente = "";
if (typeof trg.from === "string") { remitente = trg.from; }
else if (trg.from && trg.from.value && trg.from.value[0]) { remitente = trg.from.value[0].address || ""; }
let archivoAdjunto = "";
if (trg.binary && trg.binary.attachment_0 && trg.binary.attachment_0.fileName) { archivoAdjunto = trg.binary.attachment_0.fileName; }
const norm = (s) => String(s === null || s === undefined ? "" : s).trim();
const low = (s) => norm(s).toLowerCase();
const CAND_DESC = ["bien o servicio", "descripcion", "descripción", "concepto"];
const CAND_CANT = ["cantidad", "cant."];
const CAND_PU = ["precio unitario", "precio", "costo unitario", "costo"];
const hit = (v, cands) => cands.some(c => v.indexOf(c) !== -1);
// Filas realmente legibles. Con alwaysOutputData, un adjunto ilegible llega como un objeto vacio.
const filasUtiles = rows.filter(r => r && Object.keys(r).length > 0).length;
let kDesc = null, kCant = null, kPu = null, dataStart = 0;
const first = rows[0] || {};
const keys0 = Object.keys(first);
kDesc = keys0.find(k => hit(low(k), CAND_DESC)) || null;
if (kDesc) {
  kCant = keys0.find(k => k !== kDesc && hit(low(k), CAND_CANT)) || null;
  kPu = keys0.find(k => k !== kDesc && k !== kCant && hit(low(k), CAND_PU)) || null;
}
if (!kDesc || !kCant) {
  kDesc = null; kCant = null; kPu = null;
  for (let r = 0; r < rows.length; r++) {
    const row = rows[r];
    let dk = null, ck = null, pk = null;
    for (const k of Object.keys(row)) {
      const v = low(row[k]);
      if (!v) { continue; }
      if (!dk && hit(v, CAND_DESC)) { dk = k; }
      else if (!ck && hit(v, CAND_CANT)) { ck = k; }
      else if (!pk && hit(v, CAND_PU)) { pk = k; }
    }
    if (dk && ck) { kDesc = dk; kCant = ck; kPu = pk; dataStart = r + 1; break; }
  }
}
// Contrato: se busca primero en el asunto y, si no viene, en el encabezado del archivo.
let preambulo = keys0.join(" ");
const tope = dataStart > 0 ? dataStart : Math.min(rows.length, 5);
for (let r = 0; r < tope; r++) {
  const row = rows[r];
  for (const k of Object.keys(row)) { preambulo = preambulo + " " + norm(row[k]); }
}
const esMorelos = (s) => /morelos/i.test(s) || /cps\s*-?\s*16/i.test(s);
const esChiapas = (s) => /chiapas/i.test(s) || /cps\s*-?\s*15/i.test(s);
let proyecto = "CPS 15 Chiapas";
let proyectoDetectadoPor = "valor por defecto";
if (esMorelos(subject)) { proyecto = "CPS 16 Morelos"; proyectoDetectadoPor = "asunto del correo"; }
else if (esChiapas(subject)) { proyecto = "CPS 15 Chiapas"; proyectoDetectadoPor = "asunto del correo"; }
else if (esMorelos(preambulo)) { proyecto = "CPS 16 Morelos"; proyectoDetectadoPor = "encabezado del archivo"; }
else if (esChiapas(preambulo)) { proyecto = "CPS 15 Chiapas"; proyectoDetectadoPor = "encabezado del archivo"; }
const items = [];
if (kDesc && kCant) {
  for (let r = dataStart; r < rows.length; r++) {
    const row = rows[r];
    const desc = norm(row[kDesc]);
    const cant = Number(kCant ? row[kCant] : 0) || 0;
    const pu = Number(kPu ? row[kPu] : 0) || 0;
    if (!desc || cant <= 0) { continue; }
    items.push({ n: items.length + 1, descripcion: desc, cantidad: cant, precioUnitario: pu, importe: Math.round(cant * pu * 100) / 100 });
  }
}
// Motivo del rechazo, para que el log distinga un archivo ilegible de uno mal estructurado.
let motivoRechazo = "";
let tipoEvento = "Datos faltantes";
if (filasUtiles === 0) {
  motivoRechazo = "El adjunto no pudo interpretarse como hoja de calculo: no se obtuvo ninguna fila. Archivo recibido: " + (archivoAdjunto || "sin nombre") + ".";
  tipoEvento = "Error parseo archivo";
} else if (!kDesc || !kCant) {
  motivoRechazo = "Se leyeron " + filasUtiles + " filas pero ninguna contiene a la vez columna de descripcion y de cantidad. Revisar el encabezado del archivo.";
} else if (items.length === 0) {
  motivoRechazo = "Se identifico el encabezado pero ninguna fila tiene descripcion con cantidad mayor a cero.";
}
const montoTotal = Math.round(items.reduce((a, b) => a + b.importe, 0) * 100) / 100;
return [{ json: {
  folio: folio,
  proyecto: proyecto,
  proyectoDetectadoPor: proyectoDetectadoPor,
  subcontratista: "SIMCO",
  encargado: remitente,
  fechaSolicitud: $now.toISODate(),
  archivoOrigen: subject,
  archivoAdjunto: archivoAdjunto,
  filasLeidas: filasUtiles,
  columnasDetectadas: { descripcion: kDesc, cantidad: kCant, precioUnitario: kPu, filaInicioDatos: dataStart },
  motivoRechazo: motivoRechazo,
  tipoEvento: tipoEvento,
  items: items,
  totalItems: items.length,
  montoTotal: montoTotal,
  messageId: String(trg.id || "")
} }];

const rq = $("03 Normalizar Items de la RQ").first().json;
const rqPageId = $("05 Notion - Crear Cabecera RQ").first().json.id;
const catRows = $("06 Notion - Leer Catalogo de Insumos").all().map(i => i.json);
const excRows = $input.all().map(i => i.json);
const slug = (s) => String(s === null || s === undefined ? "" : s).normalize("NFD").replace(/[̀-ͯ]/g, "").toLowerCase().replace(/^property_/, "").replace(/[^a-z0-9]+/g, "");
const idx = (row) => { const m = {}; for (const k of Object.keys(row)) { m[slug(k)] = row[k]; } return m; };
const val = (m, name) => {
  const v = m[slug(name)];
  if (v === null || v === undefined) { return ""; }
  if (Array.isArray(v)) { return v.map(x => (x && x.name) ? x.name : String(x)).join(", ").trim(); }
  if (typeof v === "object") { return String(v.name || v.value || "").trim(); }
  return String(v).trim();
};
const catalogo = catRows.map(r => { const m = idx(r); return {
  id: r.id,
  d: val(m, "Bien o Servicio") || val(m, "name"),
  cat: val(m, "Categoría (Glosario)"),
  sub: val(m, "Subcategoría"),
  int: val(m, "Categoría Interna"),
  resp: val(m, "Corresponde")
}; }).filter(r => r.d);
const excepciones = excRows.map(r => { const m = idx(r); return {
  id: r.id,
  nombre: val(m, "Excepción") || val(m, "name"),
  ambito: val(m, "Ámbito"),
  condicion: val(m, "Condición"),
  cat: val(m, "Categoría (Glosario)"),
  resp: val(m, "Corresponde"),
  proyecto: val(m, "Proyecto")
}; }).filter(r => r.nombre);
const aplicables = excepciones.filter(e => !e.proyecto || e.proyecto === "Ambos" || e.proyecto === rq.proyecto);
const conCategoria = catalogo.filter(c => c.cat).length;
const payload = {
  proyecto: rq.proyecto,
  folio: rq.folio,
  items: rq.items,
  excepciones: aplicables,
  catalogo: catalogo
};
return [{ json: {
  rqPageId: rqPageId,
  folio: rq.folio,
  totalItems: rq.totalItems,
  registrosCatalogo: catalogo.length,
  catalogoConCategoria: conCategoria,
  registrosExcepciones: aplicables.length,
  clavesCrudas: Object.keys(catRows[0] || {}),
  userPrompt: JSON.stringify(payload)
} }];

// Umbral de materialidad para el punto de validacion humana.
// Solo aplica a items de confianza Media. Importe en MXN sin IVA.
const UMBRAL_HITL_MXN = 10000;

const raw = $input.first().json;
let text = "";
if (typeof raw.text === "string") { text = raw.text; }
else if (Array.isArray(raw.content)) { text = raw.content.map(c => (c && c.text) ? c.text : "").join(""); }
else if (typeof raw.content === "string") { text = raw.content; }
else { text = JSON.stringify(raw); }
text = text.replace(/```json/gi, "").replace(/```/g, "").trim();
const ini = text.indexOf("[");
const fin = text.lastIndexOf("]");
let parsed = [];
if (ini !== -1 && fin > ini) {
  try { parsed = JSON.parse(text.slice(ini, fin + 1)); } catch (e) { parsed = []; }
}
if (!Array.isArray(parsed)) { parsed = []; }
const src = $("03 Normalizar Items de la RQ").first().json;
const ctx = $("08 Construir Prompt de Clasificacion").first().json;
const CAT = ["Equipo Mayor", "Equipo Menor", "Herramientas", "Refacciones", "Insumos y Consumibles", "Mano de Obra", "Mobiliario"];
const FUENTE = ["Catálogo (exacto)", "Catálogo (análogo)", "Glosario", "Excepción", "Investigación", "Requiere criterio"];
const MAPF = { "Catalogo (exacto)": "Catálogo (exacto)", "Catalogo (analogo)": "Catálogo (análogo)", "Excepcion": "Excepción", "Investigacion": "Investigación" };
const CONF = ["Alta", "Media", "Baja"];
const RESP = ["La Cosmopolitana", "SIMCO"];
return src.items.map(it => {
  const r = parsed.find(p => Number(p.n) === Number(it.n)) || {};
  const f = MAPF[r.fuente] || r.fuente;
  const fuente = FUENTE.indexOf(f) !== -1 ? f : "Requiere criterio";
  const confianza = CONF.indexOf(r.confianza) !== -1 ? r.confianza : "Baja";
  const categoria = CAT.indexOf(r.categoria) !== -1 ? r.categoria : "";
  const corresponde = RESP.indexOf(r.corresponde) !== -1 ? r.corresponde : "";
  const importe = Math.round((Number(it.importe) || (Number(it.cantidad) * Number(it.precioUnitario)) || 0) * 100) / 100;
  let motivo = "";
  if (fuente === "Investigación" || fuente === "Requiere criterio") {
    motivo = "Fuente " + fuente + ". Se detiene sin importar el monto.";
  } else if (confianza === "Baja") {
    motivo = "Confianza Baja. Se detiene sin importar el monto.";
  } else if (confianza === "Media" && importe >= UMBRAL_HITL_MXN) {
    motivo = "Confianza Media con importe de $" + importe.toFixed(2) + " MXN, igual o mayor al umbral de $" + UMBRAL_HITL_MXN.toFixed(2) + " MXN.";
  }
  const hitl = motivo ? "Si" : "No";
  let just = String(r.justificacion || "El modelo no devolvio justificacion para este item.");
  if (r.matchId) { just = just + " [Ref. catalogo: " + r.matchId + "]"; }
  if (r.excepcionId) { just = just + " [Excepcion: " + r.excepcionId + "]"; }
  return { json: {
    rqPageId: ctx.rqPageId,
    folio: src.folio,
    n: it.n,
    descripcion: it.descripcion,
    cantidad: it.cantidad,
    precioUnitario: it.precioUnitario,
    importe: importe,
    categoria: categoria,
    subcategoria: String(r.subcategoria || ""),
    corresponde: corresponde,
    fuente: fuente,
    confianza: confianza,
    revisionHumana: hitl,
    motivoHitl: motivo || "Clasificado en automatico.",
    umbralHitl: UMBRAL_HITL_MXN,
    justificacion: just.slice(0, 1900),
    estatus: hitl === "Si" ? "Esperando aprobación" : "Procesado por IA"
  } };
});

const cls = $("10 Parsear Clasificacion IA").all().map(i => i.json);
const rq = $("03 Normalizar Items de la RQ").first().json;
const ctx = $("08 Construir Prompt de Clasificacion").first().json;
const flagged = cls.filter(c => c.revisionHumana === "Si");
const detalle = flagged.map(c => "*#" + c.n + " " + c.descripcion + "*\n   Importe: $" + Number(c.importe).toFixed(2) + " MXN  |  Fuente: " + c.fuente + "  |  Confianza: " + c.confianza + "  |  Propuesta: " + (c.corresponde || "sin determinar") + "\n   Por que se detuvo: " + c.motivoHitl + "\n   _" + c.justificacion + "_").join("\n\n");
const auto = cls.filter(c => c.revisionHumana === "No");
const porSimco = cls.filter(c => c.corresponde === "SIMCO").length;
const porCosmo = cls.filter(c => c.corresponde === "La Cosmopolitana").length;
const umbral = cls.length ? Number(cls[0].umbralHitl) : 10000;
const montoFlagged = Math.round(flagged.reduce((a, b) => a + (Number(b.importe) || 0), 0) * 100) / 100;
return [{ json: {
  rqPageId: ctx.rqPageId,
  folio: rq.folio,
  proyecto: rq.proyecto,
  montoTotal: rq.montoTotal,
  messageId: rq.messageId,
  totalItems: cls.length,
  flaggedCount: flagged.length,
  autoCount: auto.length,
  porSimco: porSimco,
  porCosmopolitana: porCosmo,
  umbralHitl: umbral,
  montoEnRevision: montoFlagged,
  requiereAprobacion: flagged.length > 0,
  detalleFlagged: detalle || "Ninguno"
} }];

